namespace Lru;

/// <summary>
/// A fixed-capacity least-recently-used cache with O(1) expected-time operations.
/// Entries live in parallel arrays linked into a doubly linked recency list
/// (head = most recent, tail = least recent); freed slots are recycled.
/// </summary>
public sealed class LruCache
{
    private const int None = -1;

    private readonly int _capacity;
    private readonly Dictionary<string, int> _index;
    private readonly Dictionary<string, int>.AlternateLookup<ReadOnlySpan<char>> _spanIndex;

    private string[] _keys;
    private string[] _values;
    private int[] _prev;
    private int[] _next;

    private int _head = None;
    private int _tail = None;
    private int _freeList = None;
    private int _used;

    public LruCache(int capacity)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(capacity, 1);
        _capacity = capacity;

        int initial = Math.Min(capacity, 1024);
        _index = new Dictionary<string, int>(initial, StringComparer.Ordinal);
        _spanIndex = _index.GetAlternateLookup<ReadOnlySpan<char>>();
        _keys = new string[initial];
        _values = new string[initial];
        _prev = new int[initial];
        _next = new int[initial];
    }

    public int Count => _index.Count;

    public void Set(ReadOnlySpan<char> key, ReadOnlySpan<char> value)
    {
        if (_spanIndex.TryGetValue(key, out int slot))
        {
            _values[slot] = value.ToString();
            MoveToFront(slot);
            return;
        }

        string keyString = key.ToString();
        slot = AllocateSlot();
        _keys[slot] = keyString;
        _values[slot] = value.ToString();
        _index.Add(keyString, slot);
        LinkAtFront(slot);

        if (_index.Count > _capacity)
        {
            RemoveSlot(_tail);
        }
    }

    public bool TryGet(ReadOnlySpan<char> key, out string? value)
    {
        if (_spanIndex.TryGetValue(key, out int slot))
        {
            MoveToFront(slot);
            value = _values[slot];
            return true;
        }

        value = null;
        return false;
    }

    public bool Remove(ReadOnlySpan<char> key)
    {
        if (!_spanIndex.TryGetValue(key, out int slot))
        {
            return false;
        }

        RemoveSlot(slot);
        return true;
    }

    private void RemoveSlot(int slot)
    {
        _index.Remove(_keys[slot]);
        Unlink(slot);
        _keys[slot] = null!;
        _values[slot] = null!;
        _next[slot] = _freeList;
        _freeList = slot;
    }

    private int AllocateSlot()
    {
        if (_freeList != None)
        {
            int slot = _freeList;
            _freeList = _next[slot];
            return slot;
        }

        if (_used == _keys.Length)
        {
            // Capacity + 1 slots are needed transiently before an eviction.
            int newSize = (int)Math.Min((long)_keys.Length * 2, (long)_capacity + 1);
            Array.Resize(ref _keys, newSize);
            Array.Resize(ref _values, newSize);
            Array.Resize(ref _prev, newSize);
            Array.Resize(ref _next, newSize);
        }

        return _used++;
    }

    private void MoveToFront(int slot)
    {
        if (slot == _head)
        {
            return;
        }

        Unlink(slot);
        LinkAtFront(slot);
    }

    private void LinkAtFront(int slot)
    {
        _prev[slot] = None;
        _next[slot] = _head;
        if (_head != None)
        {
            _prev[_head] = slot;
        }
        else
        {
            _tail = slot;
        }

        _head = slot;
    }

    private void Unlink(int slot)
    {
        int prev = _prev[slot];
        int next = _next[slot];

        if (prev != None)
        {
            _next[prev] = next;
        }
        else
        {
            _head = next;
        }

        if (next != None)
        {
            _prev[next] = prev;
        }
        else
        {
            _tail = prev;
        }
    }
}

using System.Globalization;
using System.Text;
using Lru;

using var input = new StreamReader(Console.OpenStandardInput(), Encoding.Latin1, false, 1 << 16);
using var output = new StreamWriter(Console.OpenStandardOutput(), Encoding.Latin1, 1 << 16) { AutoFlush = false };

string? header = input.ReadLine();
if (header is null || !int.TryParse(header.AsSpan().Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out int capacity) || capacity < 1)
{
    Console.Error.WriteLine("error: first line must be a positive integer capacity");
    return 1;
}

var cache = new LruCache(capacity);

while (input.ReadLine() is { } line)
{
    ReadOnlySpan<char> rest = line.AsSpan().TrimEnd('\r');
    ReadOnlySpan<char> command = NextToken(ref rest);

    switch (command)
    {
        case "SET":
        {
            ReadOnlySpan<char> key = NextToken(ref rest);
            ReadOnlySpan<char> value = NextToken(ref rest);
            cache.Set(key, value);
            break;
        }
        case "GET":
            output.Write(cache.TryGet(NextToken(ref rest), out string? cached) ? cached : "NULL");
            output.Write('\n');
            break;
        case "DEL":
            output.Write(cache.Remove(NextToken(ref rest)) ? '1' : '0');
            output.Write('\n');
            break;
        case "SIZE":
            output.Write(cache.Count);
            output.Write('\n');
            break;
        default:
            // Blank or unrecognised lines are ignored.
            break;
    }
}

output.Flush();
return 0;

static ReadOnlySpan<char> NextToken(ref ReadOnlySpan<char> rest)
{
    int space = rest.IndexOf(' ');
    ReadOnlySpan<char> token;
    if (space < 0)
    {
        token = rest;
        rest = default;
    }
    else
    {
        token = rest[..space];
        rest = rest[(space + 1)..];
    }

    return token;
}
